{
  "outcome": "deny",
  "rationale": "We deny this claim because the claimant's account of racing triggers the policy exclusion for impromptu street racing. Section PREM-4.2 specifically excludes coverage for any loss that occurs while the vehicle is used in an impromptu race.",
  "citations": [
    {
      "clause_id": "PREM-4.2",
      "quote": "We do not cover loss that occurs while the covered vehicle is used in, or in practice or preparation for, any organized or impromptu race, speed contest, stunt driving or demonstration, whether on a public road or on a closed course."
    }
  ]
}
